'use client'

import { createContext } from 'react'
import type { ReactNode } from 'react'
import { Slot, useSignals } from '@cascivo/core'
import { usePopover } from './use-popover'
import type { UsePopoverOptions, UsePopoverReturn } from './use-popover'
import styles from './popover.module.css'

const PopoverContext = createContext<UsePopoverReturn | null>(null)

export interface PopoverProps extends UsePopoverOptions {
  children: ReactNode
}

export function Popover({ children, ...options }: PopoverProps) {
  const popover = usePopover(options)
  return <PopoverContext.Provider value={popover}>{children}</PopoverContext.Provider>
}

export interface PopoverTriggerProps {
  children: ReactNode
  /**
   * Render the single child element as the trigger instead of wrapping it in
   * `PopoverTrigger`'s own `<button>` — the Slot pattern. Use this whenever the child is
   * already an interactive element (`Button`, `IconButton`, a router link): nesting a
   * `<button>` inside a `<button>` is invalid HTML, and it orphans the inner element's
   * `aria-label` on a node the accessibility tree does not expect there.
   *
   * ```tsx
   * <PopoverTrigger asChild>
   *   <IconButton label="Theme" icon={<Palette />} />
   * </PopoverTrigger>
   * ```
   */
  asChild?: boolean
}

export function PopoverTrigger({ children, asChild = false }: PopoverTriggerProps) {
  useSignals()
  // Matches `icon-button.tsx` — including `type` only on the real <button>, since a
  // slotted <a> or router link must not receive it.
  const Comp = asChild ? Slot : 'button'
  return (
    <PopoverContext.Consumer>
      {(ctx) => {
        if (!ctx) throw new Error('PopoverTrigger must be used inside <Popover>')
        const { triggerRef, toggle, anchorName, isOpen } = ctx
        return (
          <Comp
            ref={triggerRef as React.RefObject<HTMLButtonElement>}
            type={asChild ? undefined : 'button'}
            aria-expanded={isOpen.value}
            aria-haspopup="dialog"
            style={{ anchorName } as React.CSSProperties}
            onClick={toggle}
            className={styles.trigger}
          >
            {children}
          </Comp>
        )
      }}
    </PopoverContext.Consumer>
  )
}

export interface PopoverContentProps {
  children: ReactNode
  className?: string
}

export function PopoverContent({ children, className }: PopoverContentProps) {
  useSignals()
  return (
    <PopoverContext.Consumer>
      {(ctx) => {
        if (!ctx) throw new Error('PopoverContent must be used inside <Popover>')
        const { popoverRef, anchorName, isOpen } = ctx
        return (
          <div
            ref={popoverRef as React.RefObject<HTMLDivElement>}
            // eslint-disable-next-line @typescript-eslint/ban-ts-comment
            popover="auto"
            role="dialog"
            data-state={isOpen.value ? 'open' : 'closed'}
            style={{ positionAnchor: anchorName } as React.CSSProperties}
            className={[styles.content, className].filter(Boolean).join(' ')}
          >
            {children}
          </div>
        )
      }}
    </PopoverContext.Consumer>
  )
}

import { useRef } from 'react'
import { useId, useSignal, useSignalEffect } from '@cascivo/core'
import type { Signal } from '@cascivo/core'

export interface UsePopoverOptions {
  open?: boolean
  onOpenChange?: (open: boolean) => void
  placement?: 'top' | 'bottom' | 'left' | 'right'
  offset?: number
}

export interface UsePopoverReturn {
  triggerRef: React.RefObject<HTMLElement | null>
  popoverRef: React.RefObject<HTMLElement | null>
  isOpen: Signal<boolean>
  anchorName: string
  open: () => void
  close: () => void
  toggle: () => void
}

const supportsAnchor =
  typeof CSS !== 'undefined' &&
  typeof CSS.supports === 'function' &&
  CSS.supports('anchor-name: --cascivo-a')

export function usePopover(options: UsePopoverOptions = {}): UsePopoverReturn {
  // `useId`, not a module counter: the anchor name is server-rendered into a style
  // property, so a counter that keeps incrementing for the server process's lifetime
  // diverges from the client's fresh counter and breaks hydration.
  const anchorName = `--${useId('cascivo-popover')}`
  const triggerRef = useRef<HTMLElement>(null)
  const popoverRef = useRef<HTMLElement>(null)
  const isOpen = useSignal(options.open ?? false)

  // Sync controlled prop into signal during render
  if (options.open !== undefined) {
    isOpen.value = options.open
  }

  const onOpenChangeRef = useRef(options.onOpenChange)
  onOpenChangeRef.current = options.onOpenChange

  const placementRef = useRef(options.placement)
  placementRef.current = options.placement

  const offsetRef = useRef(options.offset)
  offsetRef.current = options.offset

  useSignalEffect(() => {
    const open = isOpen.value
    onOpenChangeRef.current?.(open)

    const popover = popoverRef.current
    if (!popover) return

    if (open) {
      try {
        popover.showPopover()
      } catch {
        // Already shown or browser doesn't support Popover API
      }
    } else {
      try {
        popover.hidePopover()
      } catch {
        // Already hidden
      }
    }

    // Fallback positioning when CSS Anchor Positioning is unsupported
    if (!supportsAnchor && open) {
      const trigger = triggerRef.current
      if (!trigger) return
      const rect = trigger.getBoundingClientRect()
      const placement = placementRef.current ?? 'bottom'
      const offset = offsetRef.current ?? 4
      if (placement === 'bottom') {
        popover.style.top = `${rect.bottom + offset + window.scrollY}px`
        popover.style.left = `${rect.left + window.scrollX}px`
      } else if (placement === 'top') {
        popover.style.top = `${rect.top - offset + window.scrollY}px`
        popover.style.left = `${rect.left + window.scrollX}px`
        popover.style.transform = 'translateY(-100%)'
      } else if (placement === 'left') {
        popover.style.top = `${rect.top + window.scrollY}px`
        popover.style.left = `${rect.left - offset + window.scrollX}px`
        popover.style.transform = 'translateX(-100%)'
      } else if (placement === 'right') {
        popover.style.top = `${rect.top + window.scrollY}px`
        popover.style.left = `${rect.right + offset + window.scrollX}px`
      }
    }
  })

  // Listen for popover hide (light-dismiss clicks)
  useSignalEffect(() => {
    const popover = popoverRef.current
    if (!popover) return
    const handler = (e: Event) => {
      const toggleEvent = e as ToggleEvent
      if (toggleEvent.newState === 'closed') {
        isOpen.value = false
      }
    }
    popover.addEventListener('toggle', handler)
    return () => popover.removeEventListener('toggle', handler)
  })

  return {
    triggerRef,
    popoverRef,
    isOpen,
    anchorName,
    open: () => {
      isOpen.value = true
    },
    close: () => {
      isOpen.value = false
    },
    toggle: () => {
      isOpen.value = !isOpen.value
    },
  }
}

@layer cascivo.component {
  .trigger {
    /* Trigger inherits button styles from the consuming component */
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-block-size: 1.5rem; /* 24px — WCAG 2.5.8 target size */
    min-inline-size: 1.5rem;
  }

  .content {
    position: fixed;
    inset: auto;
    margin: 0;
    padding: var(--cascivo-space-3);
    background: var(--cascivo-color-surface);
    border: 1px solid var(--cascivo-color-border);
    border-radius: var(--cascivo-radius-overlay);
    box-shadow: var(--cascivo-shadow-md);

    /* CSS Anchor Positioning — supported browsers */
    @supports (anchor-name: --a) {
      position-try-fallbacks:
        flip-block,
        flip-inline,
        flip-block flip-inline;
      inset-block-start: anchor(end);
      inset-inline-start: anchor(start);
    }

    /* Enter animation */
    opacity: 1;
    translate: 0 0;
    transition:
      opacity var(--cascivo-motion-enter),
      translate var(--cascivo-motion-enter),
      display var(--cascivo-motion-enter) allow-discrete,
      overlay var(--cascivo-motion-enter) allow-discrete;

    @starting-style {
      opacity: 0;
      translate: 0 calc(-1 * var(--cascivo-space-2));
    }

    &[data-state='closed'] {
      opacity: 0;
      translate: 0 calc(-1 * var(--cascivo-space-2));
      transition:
        opacity var(--cascivo-motion-exit),
        translate var(--cascivo-motion-exit),
        display var(--cascivo-motion-exit) allow-discrete,
        overlay var(--cascivo-motion-exit) allow-discrete;
    }
  }
}

import type { ComponentMeta } from '@cascivo/core'

export const meta: ComponentMeta = {
  name: 'Popover',
  description: 'Anchored floating panel built on CSS Anchor Positioning + Popover API',
  category: 'overlay',
  clientJs: 'required',
  states: ['open', 'closed'],
  variants: [],
  sizes: [],
  props: [
    {
      name: 'children',
      description: 'A PopoverTrigger and PopoverContent pair.',
      type: 'React.ReactNode',
      required: true,
    },
    {
      name: 'open',
      description: 'Whether the component is open (controlled).',
      type: 'boolean',
      required: false,
    },
    {
      name: 'onOpenChange',
      description: 'Called with the next open state when it changes.',
      type: '(open: boolean) => void',
      required: false,
    },
    {
      name: 'placement',
      description: 'Side of the trigger the panel opens on: `bottom`, `top`, `left` or `right`.',
      type: "'top' | 'bottom' | 'left' | 'right'",
      required: false,
      default: 'bottom',
    },
    {
      name: 'offset',
      description: 'Distance (px) between the trigger and the panel.',
      type: 'number',
      required: false,
      default: '4',
    },
  ],
  tokens: [
    '--cascivo-color-surface',
    '--cascivo-color-border',
    '--cascivo-radius-md',
    '--cascivo-shadow-md',
    '--cascivo-motion-enter',
    '--cascivo-motion-exit',
  ],
  accessibility: {
    role: 'dialog',
    wcag: '2.2-AA',
    keyboard: ['Escape'],
  },
  examples: [
    {
      title: 'Basic',
      code: `<Popover>
  <PopoverTrigger>Open settings</PopoverTrigger>
  <PopoverContent>
    <form>…</form>
  </PopoverContent>
</Popover>`,
    },
    {
      title: 'Controlled with placement',
      code: `<Popover open={isOpen} onOpenChange={setIsOpen} placement="top">
  <PopoverTrigger>Filters</PopoverTrigger>
  <PopoverContent><FilterForm /></PopoverContent>
</Popover>`,
    },
  ],
  dependencies: ['@cascivo/core'],
  tags: ['overlay', 'floating', 'anchor', 'popover'],
  intent: {
    whenToUse: [
      'Showing rich, interactive content anchored to a trigger that the user must explicitly open by clicking',
      'Lightweight transient panels (forms, pickers, detail cards) that do not need to block the rest of the page',
    ],
    whenNotToUse: [
      'A short, non-interactive text hint on hover/focus — use Tooltip',
      'A task that must capture focus and block interaction with the page — use Modal',
      'Preview content revealed on hover without a click — use HoverCard',
    ],
    antiPatterns: [
      {
        bad: '<Tooltip content={<form>...</form>}>',
        good: '<Popover><PopoverTrigger>…</PopoverTrigger><PopoverContent><form>…</form></PopoverContent></Popover>',
        why: 'Tooltips are non-interactive and hover-driven; interactive content needs a click-opened dialog popover that users can move focus into',
      },
    ],
    related: [
      {
        name: 'Tooltip',
        relationship: 'alternative',
        reason: 'Use for brief non-interactive hints, not interactive content',
      },
      {
        name: 'HoverCard',
        relationship: 'alternative',
        reason: 'Use when the panel should open on hover rather than click',
      },
      {
        name: 'Modal',
        relationship: 'alternative',
        reason: 'Use when the overlay must be blocking and focus-trapping',
      },
    ],
    a11yRationale:
      'The trigger is a real <button> with aria-haspopup="dialog" and aria-expanded reflecting open state, and the panel uses role="dialog" via the native Popover API so Escape-to-close and light-dismiss come from the platform rather than custom handlers.',
    flexibility: [
      {
        area: 'token names',
        level: 'strict',
        note: 'Panel styling must resolve to the listed --cascivo-* tokens',
      },
      {
        area: 'content',
        level: 'flexible',
        note: 'Trigger and panel content are arbitrary children supplied by the consumer',
      },
    ],
  },
}
